// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz parameters: from (actor), v (value), and a bool chooseFail to control helper behaviour
    function testFuzz_property(address from, uint256 v, bool chooseFail) public {
        // keep _tos length at least 1 by constructing a dynamic array with one entry
        address[] memory tos = new address[](1);

        // deploy a helper that can be toggled to either revert or accept the call
        // we deploy here per-run so the fuzzer still controls `from` and `v`
        RecorderOrReverter helper = new RecorderOrReverter();
        // set helper mode according to fuzzed boolean
        helper.setShouldFail(chooseFail);

        tos[0] = address(helper);

        // The reference implementation guarantees it does not revert for any inputs where _tos.length>0.
        // The mutant checks the low-level call success and will revert when the callee reverts.
        // We observe whether transfer reverts by try/catch and assert that for the reference it never reverts.

        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule: reference never reverts when _tos.length>0, so ok must be true for all inputs.
        // The mutant will be caught by the fuzzer when helper is set to revert (chooseFail==true), causing ok==false.
        assertTrue(ok);
    }
}

// Helper that can either revert on the called selector or accept and record the call
contract RecorderOrReverter {
    bool public shouldFail;

    // store last received parameters when not failing
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public callCount;

    function setShouldFail(bool b) public { shouldFail = b; }

    // This matches selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external {
        if (shouldFail) {
            revert("forced revert");
        }
        lastFrom = from;
        lastTo = to;
        lastV = v;
        callCount += 1;
    }

    // payable fallback to accept ether if sent; does nothing else
    receive() external payable {}
}
